        int left = 0, ans = 0;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            cnt.put(c, cnt.getOrDefault(c, 0) + 1);
            // 种类超过 k 就缩左端，频次归零则删键
            while (cnt.size() > k) {
