import java.util.*;

class Solution {
    public int search(int[] nums, int target) {
        int left = 0;
        int right = nums.length - 1; // 闭区间右端是最后一个下标。

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] == target) {
                return mid;
            }

            if (nums[mid] < target) {
                left = mid + 1; // 左半及中点都更小，丢掉。
            } else {
                right = mid - 1; // 右半及中点都更大，丢掉。
            }
        }

        return -1;
    }
}

