// 换题只改转移：爬楼梯改成滚动 a+b 且 dp 初值是走到 1、2 阶的方法数；打家劫舍改成 max(不偷=prev1, 偷=nums[i]+prev2)；乘积最大要同时滚动以 i 结尾的最大与最小
static int maxSubArray(int[] nums) {
    int bestEnd = nums[0];
    int ans = nums[0];
    for (int i = 1; i < nums.length; i++) {
        bestEnd = Math.max(nums[i], bestEnd + nums[i]);
        ans = Math.max(ans, bestEnd);
    }
    return ans;
}

