import java.util.*;

class Solution {
    public double myPow(double x, int n) {
        // 用 long 存指数，-Integer.MIN_VALUE 才能取负而不溢出。
        long exponent = n;

        if (exponent < 0) {
            x = 1.0 / x;
            exponent = -exponent;
        }

        double answer = 1.0;
        double base = x;

        while (exponent > 0) {
            // 最低位为 1 时，当前 base 正好是这一位要乘进答案的因子。
            if ((exponent & 1L) == 1L) {
                answer *= base;
            }

            base *= base;     // 指数减半后，下一位对应的底数是平方。
            exponent >>= 1;
        }

        return answer;
    }
}

class Solution {
    public int divide(int dividend, int divisor) {
        // 最小 int 除以 -1 会超出 int 上界
        if (dividend == Integer.MIN_VALUE && divisor == -1) {
            return Integer.MAX_VALUE;
        }

        long a = Math.abs((long) dividend);
        long b = Math.abs((long) divisor);
        // 符号不同则商为负
        int sign = ((dividend ^ divisor) < 0) ? -1 : 1;

        long ans = 0;
        while (a >= b) {
            long cur = b;
            long count = 1;
            // 左移找到当前还能一次减掉的最大一块
            while ((cur << 1) <= a) {
                cur <<= 1;
                count <<= 1;
            }
            a -= cur;
            ans += count;
        }

        return sign > 0 ? (int) ans : (int) -ans;
    }
}

import java.util.*;

class Solution {
    // 返回 {能够达到的最小值, 达到它的最少操作次数}。
    public long[] minimize(long n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n 必须是正整数");
        }
        if (n == 1) {
            return new long[]{1L, 0L};
        }

        long x = n;
        long radical = 1L;
        List<Integer> exponents = new ArrayList<>();

        // 2 单独试除，避免后面只走奇数时漏掉偶因子。
        if (x % 2 == 0) {
            int exponent = 0;
            while (x % 2 == 0) {
                x /= 2;
                exponent++;
            }
            radical *= 2;
            exponents.add(exponent);
        }

        // 只枚举奇因子；factor <= x / factor 是为了不让 factor*factor 溢出。
        for (long factor = 3; factor <= x / factor; factor += 2) {
            if (x % factor != 0) continue;

            int exponent = 0;
            while (x % factor == 0) {
                x /= factor;
                exponent++;
            }

            radical *= factor;
            exponents.add(exponent);
        }

        // 剩下的 x>1 必是质数，指数只能是 1，也要计入 radical。
        if (x > 1) {
            radical *= x;
            exponents.add(1);
        }

        int maxExponent = 0;
        for (int exponent : exponents) {
            maxExponent = Math.max(maxExponent, exponent);
        }

        // 每次开方指数减半，目标指数必须是不小于最大指数的 2 的幂。
        int targetExponent = 1;
        int sqrtCount = 0;
        while (targetExponent < maxExponent) {
            targetExponent *= 2;
            sqrtCount++;
        }

        // 指数不齐时，一次乘法就能把它们补到同一个 targetExponent。
        boolean needMultiply = false;
        for (int exponent : exponents) {
            if (exponent != targetExponent) {
                needMultiply = true;
                break;
            }
        }

        long operations = sqrtCount + (needMultiply ? 1 : 0);
        return new long[]{radical, operations};
    }
}

import java.util.*; // 模板导入，本题只对数组做异或。

class Solution {
    public int singleNumber(int[] nums) {
        int answer = 0;

        for (int num : nums) {
            // a^a 得 0，成对的数抵消，最后只留下出现一次的数。
            answer ^= num;
        }

        return answer;
    }
}

import java.util.*; // 模板导入，投票只用 candidate 和 count。

class Solution {
    public int majorityElement(int[] nums) {
        int candidate = 0;
        int count = 0;

        for (int num : nums) {
            // 票被抵消光后，当前元素重新作为候选。
            if (count == 0) {
                candidate = num;
            }

            count += (num == candidate) ? 1 : -1;
        }

        // 多数元素多到抵消不完，循环结束时它仍是 candidate。
        return candidate;
    }
}

class Solution {
    public int hammingWeight(int n) {
        int count = 0;
        while (n != 0) {
            // n-1 翻转最低的 1 及其右侧，相与后只去掉这一个 1。
            n &= (n - 1);
            count++;
        }
        return count;
    }
}

import java.util.*;

class Solution {
    public boolean isStraight(int[] nums) {
        Arrays.sort(nums);

        int first = 0;
        // 0 是万能牌，先跳过，后面只检查真实牌面。
        while (first < nums.length && nums[first] == 0) {
            first++;
        }

        // 全是大小王，任意顺子都能凑出。
        if (first == nums.length) {
            return true;
        }

        for (int i = first + 1; i < nums.length; i++) {
            // 非 0 牌重复就无法排成连续顺子。
            if (nums[i] == nums[i - 1]) {
                return false;
            }
        }

        // 最大牌与最小非 0 牌跨度小于 5，缺口不超过 0 的个数。
        return nums[nums.length - 1] - nums[first] < 5;
    }
}

class Solution {
    public int findKthNumber(int n, int k) {
        int current = 1;
        long remaining = k - 1L; // 1 已占字典序第一位，还要再跳过 k-1 个数。

        while (remaining > 0) {
            long steps = countSteps(n, current, current + 1L);

            if (steps <= remaining) {
                // 目标不在这棵前缀子树，整棵跳过。
                current++;
                remaining -= steps;
            } else {
                // 目标在子树内，进入下一层最左孩子并吃掉当前节点。
                current *= 10;
                remaining--;
            }
        }
        return current;
    }

    private long countSteps(int n, long first, long next) {
        long steps = 0;
        while (first <= n) {
            // 本层落在 [first, next) 且不超过 n 的数字个数。
            steps += Math.min((long) n + 1, next) - first;
            first *= 10;
            next *= 10;
        }
        return steps;
    }
}

class Solution {
    public int countDigitOne(int n) {
        long digit = 1, ans = 0;
        // 从个位开始：high 是更高位，cur 是当前位，low 是更低位组成的数
        long high = n / 10, cur = n % 10, low = 0;
        while (high != 0 || cur != 0) {
            if (cur == 0) {
                // 当前位是 0：只有高位更小的数才会在这一位出现 1
                ans += high * digit;
            } else if (cur == 1) {
                // 当前位正好是 1：高位更小的全部计入，高位相等时低位只能取到 low
                ans += high * digit + low + 1;
            } else {
                // 当前位大于 1：高位取到 high 时这一位也已经出现过完整一轮 1
                ans += (high + 1) * digit;
            }
            low += cur * digit;
            cur = high % 10;
            high /= 10;
            digit *= 10; // 处理完当前位后，权重进到下一位
        }
        return (int) ans;
    }
}

class Solution {
    public int trailingZeroes(int n) {
        int ans = 0;
        while (n > 0) {
            // 依次累加 n/5、n/25、n/125...
            n /= 5;
            ans += n;
        }
        return ans;
    }
}

public class TrailingZeroesOfFactorial {
    public long trailingZeroes(long n) {
        long ans = 0;

        // 每一层商都是更高次幂 5 额外贡献的个数
        while (n > 0) {
            n /= 5;
            ans += n;
        }

        return ans;
    }
}

public class LastNonZeroDigitOfFactorial {
    // 小于 5 时没有尾零，末位可直接查表
    private static final int[] BASE = {1, 1, 2, 6, 4};

    public int lastNonZeroDigit(long n) {
        if (n < 5) {
            return BASE[(int) n];
        }

        // 每 5 个数抵消一组 10，商和余数分开算
        long quotient = n / 5;
        long remainder = n % 5;

        int leftPart = lastNonZeroDigit(quotient);
        int remainPart = BASE[(int) remainder];
        // 每组多出来的 2 还要乘回去，只留个位
        int extraTwo = pow2Mod10(quotient);

        return leftPart * remainPart * extraTwo % 10;
    }

    private int pow2Mod10(long exp) {
        if (exp == 0) {
            return 1;
        }

        // 指数非 0 且被 4 整除时个位是 6，循环从 6 起
        int[] cycle = {6, 2, 4, 8};
        return cycle[(int) (exp % 4)];
    }
}

class Solution {
    public int lastRemaining(int n, int m) {
        if (n <= 0 || m <= 0) {
            throw new IllegalArgumentException("n 和 m 必须为正数");
        }

        int answer = 0; // 只剩 1 人时，存活编号就是 0。

        for (int size = 2; size <= n; size++) {
            // 删掉一人后下标整体加 m，再映射回长度为 size 的圈。
            answer = (answer + m) % size;
        }

        return answer;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> josephus(int n, int m) {
        List<Integer> people = new ArrayList<>();
        // 按 1..n 入圈，下标即当前圈上的位置
        for (int i = 1; i <= n; i++) {
            people.add(i);
        }
        List<Integer> ans = new ArrayList<>();
        int index = 0;
        while (!people.isEmpty()) {
            // 从上次删除后的位置再数 m-1 个人
            index = (index + m - 1) % people.size();
            // 删除后后续元素前移，index 已指向下一个人
            ans.add(people.remove(index));
        }
        return ans;
    }
}

class Solution {
    // 返回先手第一步应取多少个；返回 -1 表示面对完美对手无必胜首步。
    public int firstMove(int balls) {
        int move = balls % 6; // 一轮合计凑成 6，余数就是先手该先拿走的个数。
        return move == 0 ? -1 : move;
    }
